(532379, 53677, 6130, '<td valign="top">I like this a lot.</td>', 'I like this a lot.', '2004-01-05 12:34:26.000000', NULL, 1),
(532380, 53787, 6130, '<td valign="top">Lovely.</td>', 'Lovely.', '2004-01-05 12:34:54.000000', NULL, 1),
(532382, 53742, 6130, '<td valign="top">Nice and looks funny.</td>', 'Nice and looks funny.', '2004-01-05 12:35:35.000000', NULL, 1),
(532385, 53705, 6130, '<td valign="top">Good job and I like it very much.</td>', 'Good job and I like it very much.', '2004-01-05 12:36:44.000000', NULL, 1),
