(532427, 52863, 772, '<td valign="top">great shot :)</td>', 'great shot :)', '2004-01-05 13:01:59.000000', NULL, 1),
(532431, 53428, 13136, '<td valign="top">Nice. All the spray across the face really emphasises the action. Good shot.</td>', 'Nice. All the spray across the face really emphasises the action. Good shot.', '2004-01-05 13:05:41.000000', NULL, 1),
(532433, 53826, 13136, '<td valign="top">I might have gone vertical on this instead of horizontal. Otherwise, good catch of the action. Nice shot.</td>', 'I might have gone vertical on this instead of horizontal. Otherwise, good catch of the action. Nice shot.', '2004-01-05 13:07:18.000000', NULL, 1),
(532434, 53439, 13136, '<td valign="top">Looks like you lost a whole lot of definition when you shrunk the size. Nice catch on the flame coming out of the barrel.</td>', 'Looks like you lost a whole lot of definition when you shrunk the size. Nice catch on the flame coming out of the barrel.', '2004-01-05 13:08:13.000000', NULL, 1),
(532437, 53767, 13136, '<td valign="top">Main subject appears to be the sunset instead of the "Action" of the jet ski.</td>', 'Main subject appears to be the sunset instead of the "Action" of the jet ski.', '2004-01-05 13:10:16.000000', NULL, 1),
(532439, 53442, 13136, '<td valign="top">Winner of the longest title. Nice contrast betwen the stillness of the reflection and action behind it.</td>', 'Winner of the longest title. Nice contrast betwen the stillness of the reflection and action behind it.', '2004-01-05 13:11:29.000000', NULL, 1),
(532443, 53834, 13136, '<td valign="top">This looks like a panning shot. You got a great "aura" effect on this one. Good work.</td>', 'This looks like a panning shot. You got a great "aura" effect on this one. Good work.', '2004-01-05 13:17:11.000000', NULL, 1),
(532447, 52925, 13136, '<td valign="top">Probably should have cropped out the object on the bottom left. A little on the grainy side.</td>', 'Probably should have cropped out the object on the bottom left. A little on the grainy side.', '2004-01-05 13:18:45.000000', NULL, 1),
(532449, 53835, 13136, '<td valign="top">I know it''s hard to stop action with a wide DOF, but the out of focus water in the back pulls my eye away from the rest. Maybe more light?</td>', 'I know it''s hard to stop action with a wide DOF, but the out of focus water in the back pulls my eye away from the rest. Maybe more light?', '2004-01-05 13:20:23.000000', NULL, 1),
(532450, 53441, 15291, '<td valign="top">Sorry just doesn''t meet the challenge.</td>', 'Sorry just doesn''t meet the challenge.', '2004-01-05 13:20:23.000000', NULL, 1),
(532451, 53644, 13136, '<td valign="top">The boat "Action" is too small a subject. Sunset seems to be primary in this shot.</td>', 'The boat "Action" is too small a subject. Sunset seems to be primary in this shot.', '2004-01-05 13:21:07.000000', NULL, 1),
(532452, 53672, 13136, '<td valign="top">Sorry, I really can''t tell what this is a picture of.</td>', 'Sorry, I really can''t tell what this is a picture of.', '2004-01-05 13:22:21.000000', NULL, 1),
(532453, 53152, 13136, '<td valign="top">Wow. Those feet really jump out of the picture. Maybe a bit too saturated? Clear shot though. Clever title (whoever thinks of ducks as marching?).</td>', 'Wow. Those feet really jump out of the picture. Maybe a bit too saturated? Clear shot though. Clever title (whoever thinks of ducks as marching?).', '2004-01-05 13:24:02.000000', NULL, 1),
(532455, 53666, 13136, '<td valign="top">Makes me dizzy just to look at it. I like the trees encroaching on the right side. They stand out still and stark and help emphasise the motion.</td>', 'Makes me dizzy just to look at it. I like the trees encroaching on the right side. They stand out still and stark and help emphasise the motion.', '2004-01-05 13:25:21.000000', NULL, 1),
(532456, 53363, 10702, '<td valign="top">nice smotth ligjting, but dont like the movement of his hand  :)</td>', 'nice smotth ligjting, but dont like the movement of his hand  :)', '2004-01-05 13:25:27.000000', NULL, 1),
(532457, 53656, 13136, '<td valign="top">I like the framing and action, but the shot looks a bit faded out.</td>', 'I like the framing and action, but the shot looks a bit faded out.', '2004-01-05 13:25:55.000000', NULL, 1),
(532459, 53751, 13136, '<td valign="top">Good concept. You even got the day-night transition in the right direction. Nice shot.</td>', 'Good concept. You even got the day-night transition in the right direction. Nice shot.', '2004-01-05 13:27:28.000000', NULL, 1),
(532460, 53816, 10702, '<td valign="top">action ......</td>', 'action ......', '2004-01-05 13:28:12.000000', NULL, 1),
(532461, 53719, 10702, '<td valign="top">Brilliant  :)</td>', 'Brilliant  :)', '2004-01-05 13:28:59.000000', NULL, 1),
(532463, 52844, 10702, '<td valign="top">Awesome, one of the best "movement" shots I''ve seen.      .:10:.</td>', 'Awesome, one of the best "movement" shots I''ve seen.      .:10:.', '2004-01-05 13:40:09.000000', NULL, 1),
