(532466, 53676, 13136, '<td valign="top">Out of focus and not well lit.</td>', 'Out of focus and not well lit.', '2004-01-05 13:46:42.000000', NULL, 1),
(532467, 53499, 10702, '<td valign="top">Nice action shot, my favorite one in this challenge, nice work.   .:10:.</td>', 'Nice action shot, my favorite one in this challenge, nice work.   .:10:.', '2004-01-05 13:47:29.000000', NULL, 1),
(532468, 53661, 13136, '<td valign="top">Interesting effect. Zoom while shooting?</td>', 'Interesting effect. Zoom while shooting?', '2004-01-05 13:47:55.000000', NULL, 1),
(532469, 53692, 13136, '<td valign="top">The aura almost makes it look like the person is pasted on a shot of the ice. Good effect.</td>', 'The aura almost makes it look like the person is pasted on a shot of the ice. Good effect.', '2004-01-05 13:49:02.000000', NULL, 1),
(532470, 53131, 13136, '<td valign="top">A bit too crowded. Nice light and color and just the right amount of blur onthe two foreground subjects.</td>', 'A bit too crowded. Nice light and color and just the right amount of blur onthe two foreground subjects.', '2004-01-05 13:50:35.000000', NULL, 1),
(532471, 53642, 13136, '<td valign="top">Maybe too fast a shutter speed. Looks like posing standing still. No real indication of motion. Oh, now I see the left ski raised and both arched up. Now I get it.</td>', 'Maybe too fast a shutter speed. Looks like posing standing still. No real indication of motion. Oh, now I see the left ski raised and both arched up. Now I get it.', '2004-01-05 13:52:48.000000', NULL, 1),
(532472, 53477, 13136, '<td valign="top">Probably needed to be back a bit to show her in the air better. Just the right amount of blur.</td>', 'Probably needed to be back a bit to show her in the air better. Just the right amount of blur.', '2004-01-05 13:53:48.000000', NULL, 1),
(532475, 53840, 9448, '<td valign="top">Nice horiz. banding... you got a Canon?</td>', 'Nice horiz. banding... you got a Canon?', '2004-01-05 13:57:55.000000', NULL, 1),
(532476, 53825, 13136, '<td valign="top">Was that all pasted together to look like that or did you really time the shot just right? Either way, good shot.</td>', 'Was that all pasted together to look like that or did you really time the shot just right? Either way, good shot.', '2004-01-05 13:58:24.000000', NULL, 1),
(532482, 53467, 509, '<td valign="top">Lol, it would seem that two people were at the same game = P<br/>Nice shot, but it would be nice to see the puck, I can''t tell if it is behind the stick or already in the goalie''s glove.  A faster shutter speed might have frozen hte action a little more too (the player is a little blurry).</td>', 'Lol, it would seem that two people were at the same game = PNice shot, but it would be nice to see the puck, I can''t tell if it is behind the stick or already in the goalie''s glove.  A faster shutter speed might have frozen hte action a little more too (the player is a little blurry).', '2004-01-05 14:06:02.000000', NULL, 1),
(532486, 53193, 13136, '<td valign="top">I like how the spray of water comes off the net during the cast.</td>', 'I like how the spray of water comes off the net during the cast.', '2004-01-05 14:08:15.000000', NULL, 1),
(532487, 53756, 9448, '<td valign="top">Border over feet -- boo!</td>', 'Border over feet -- boo!', '2004-01-05 14:08:18.000000', NULL, 1),
