(532490, 52844, 10593, '<td valign="top">this is an amazing shot.  i cant wait to see how you did it.</td>', 'this is an amazing shot.  i cant wait to see how you did it.', '2004-01-05 14:10:38.000000', NULL, 1),
(532491, 53439, 509, '<td valign="top">This is a good idea, and excellent timing on your part.  You might want to get a better camera though...the compression and artifacts really detract from this.  Great take on the challenge though</td>', 'This is a good idea, and excellent timing on your part.  You might want to get a better camera though...the compression and artifacts really detract from this.  Great take on the challenge though', '2004-01-05 14:10:40.000000', NULL, 1),
(532492, 53467, 13136, '<td valign="top">It''s amazing what perspective can do. This almost looks like a toy setup instead of real life. good action shot.</td>', 'It''s amazing what perspective can do. This almost looks like a toy setup instead of real life. good action shot.', '2004-01-05 14:11:08.000000', NULL, 1),
(532494, 53689, 509, '<td valign="top">The posts framing the outside of the shot is a nice and interesting touch.  Nice work</td>', 'The posts framing the outside of the shot is a nice and interesting touch.  Nice work', '2004-01-05 14:12:15.000000', NULL, 1),
(532495, 53694, 10047, '<td valign="top">Did #17 forget his job? He looks a little large to be a Scrum Half. Excellent photo and great colors. This makes me want to try and get some snaps of the Toledo Celtics. Maybe some low level shots with the scrum a bit more horizontal.</td>', 'Did #17 forget his job? He looks a little large to be a Scrum Half. Excellent photo and great colors. This makes me want to try and get some snaps of the Toledo Celtics. Maybe some low level shots with the scrum a bit more horizontal.', '2004-01-05 14:16:07.000000', NULL, 1),
(532496, 53833, 10047, '<td valign="top">Maybe a little overexposed. Not sure if you could do something to add more contrast.</td>', 'Maybe a little overexposed. Not sure if you could do something to add more contrast.', '2004-01-05 14:17:45.000000', NULL, 1),
(532498, 53661, 10047, '<td valign="top">Maybe too much motion blur. Even with the title helping it is difficult to discern. Great colors.</td>', 'Maybe too much motion blur. Even with the title helping it is difficult to discern. Great colors.', '2004-01-05 14:19:49.000000', NULL, 1),
(532500, 53642, 10047, '<td valign="top">Excellent capture. I ''d like to see it with some motion blur added.</td>', 'Excellent capture. I ''d like to see it with some motion blur added.', '2004-01-05 14:21:10.000000', NULL, 1),
(532503, 53431, 10047, '<td valign="top">Nice shot. I wonder if a black napkin or darker background would have brought the action out more.</td>', 'Nice shot. I wonder if a black napkin or darker background would have brought the action out more.', '2004-01-05 14:22:34.000000', NULL, 1),
(532505, 53439, 10047, '<td valign="top">Maybe a little overprocessed. I tried getting a capture like this, but your timing is better than mine.</td>', 'Maybe a little overprocessed. I tried getting a capture like this, but your timing is better than mine.', '2004-01-05 14:24:07.000000', NULL, 1),
