INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(533039, 53787, 13897, '<td valign="top">I can''t vote on member challenges. However, I fully expect this image to ribbon. <br/> Very nice work.</td>', 'I can''t vote on member challenges. However, I fully expect this image to ribbon.  Very nice work.', '2004-01-06 00:37:42.000000', NULL, 1),
(533046, 53656, 8054, '<td valign="top">What would be a great image suffers from excessive compression.</td>', 'What would be a great image suffers from excessive compression.', '2004-01-06 01:07:07.000000', NULL, 1),
(533061, 53839, 4007, '<td valign="top">Wow that looks like fun.  A great capture too, with so much height off the water.  It looks like everything is a little bleached and glare covered from too much sunlight, but otherwise a great shot.</td>', 'Wow that looks like fun.  A great capture too, with so much height off the water.  It looks like everything is a little bleached and glare covered from too much sunlight, but otherwise a great shot.', '2004-01-06 02:25:20.000000', NULL, 1),
(533073, 53725, 12802, '<td valign="top">Very nice shot here, good high shutter speed to capture the water splshes.  Can almost see this in B&amp;W or masking out the guy and having everything else B&amp;W.  Well done! 9</td>', 'Very nice shot here, good high shutter speed to capture the water splshes.  Can almost see this in B&W or masking out the guy and having everything else B&W.  Well done! 9', '2004-01-06 02:57:01.000000', NULL, 1),
(533074, 53787, 12591, '<td valign="top">Excellent! Calm power.</td>', 'Excellent! Calm power.', '2004-01-06 02:57:11.000000', NULL, 1),
(533075, 53642, 12802, '<td valign="top">Nice clear shot, wished though that I could see some motion.  He looks as if he could be standing there.  Maybe experiment with following your subject with the camera when taking the shot.  The background will appear blurred, but your subject will be still. (Does take practice though)  8</td>', 'Nice clear shot, wished though that I could see some motion.  He looks as if he could be standing there.  Maybe experiment with following your subject with the camera when taking the shot.  The background will appear blurred, but your subject will be still. (Does take practice though)  8', '2004-01-06 02:58:18.000000', NULL, 1),
(533076, 53039, 12802, '<td valign="top">Really good shot here, well captured.  Would have had top marks had you sharpened it up a bit more.  If you had done this, the tail and wings would have stood out more. Well done though!! 9</td>', 'Really good shot here, well captured.  Would have had top marks had you sharpened it up a bit more.  If you had done this, the tail and wings would have stood out more. Well done though!! 9', '2004-01-06 03:02:19.000000', NULL, 1),
(533077, 53539, 12802, '<td valign="top">Very cute shot, wonder if he''s getting some action... (Head back out from the gutter!)<br/> <br/>Normally I''d say something about the cropping, but this just feels right. As if the other one (female?) is just sneaking in to give a wee kiss.  The expression on his face is brilliant!... 10</td>', 'Very cute shot, wonder if he''s getting some action... (Head back out from the gutter!) Normally I''d say something about the cropping, but this just feels right. As if the other one (female?) is just sneaking in to give a wee kiss.  The expression on his face is brilliant!... 10', '2004-01-06 03:16:43.000000', NULL, 1),
(533080, 53734, 12802, '<td valign="top">Very nice, good clear shot! The background of black was a good choice, goes well with her hair.  Good fast exposure to get the water motionless. 9</td>', 'Very nice, good clear shot! The background of black was a good choice, goes well with her hair.  Good fast exposure to get the water motionless. 9', '2004-01-06 03:33:45.000000', NULL, 1),
(533081, 53677, 12802, '<td valign="top">Bet that''s cold!  One we saw last year and the water was 4c...<br/> <br/>Good shot here, nicely captured water splashes.  Maybe could have cropped a bit off the top? Or, just shown one swimmer with a portrait shot?  9/10</td>', 'Bet that''s cold!  One we saw last year and the water was 4c... Good shot here, nicely captured water splashes.  Maybe could have cropped a bit off the top? Or, just shown one swimmer with a portrait shot?  9/10', '2004-01-06 03:46:20.000000', NULL, 1),
(533082, 52965, 12802, '<td valign="top">:-) Good shot here, shows the emotion in the kids faces.  The movement is good.  Also like the guy in the background who looks as if he''s about to fall over!</td>', ':-) Good shot here, shows the emotion in the kids faces.  The movement is good.  Also like the guy in the background who looks as if he''s about to fall over!', '2004-01-06 03:47:10.000000', NULL, 1),
(533091, 53689, 5158, '<td valign="top">One of my favorits this time: lives from symmetry, the combination of sharpness with blured motion and from the earthy colors. Most amazing to me is how well you made all swings and post sharp and the grass and far distance blurred to produce the right background. <br/>Very well done. Good luck to you.</td>', 'One of my favorits this time: lives from symmetry, the combination of sharpness with blured motion and from the earthy colors. Most amazing to me is how well you made all swings and post sharp and the grass and far distance blurred to produce the right background. Very well done. Good luck to you.', '2004-01-06 05:01:35.000000', NULL, 1),
(533095, 53734, 5158, '<td valign="top">I do have three problems with this image:<br/>1. To me it is more ''stopped action'' rather then action itself.<br/>2. It''''s another water drop image as there are plenty of.<br/>3. I only can give you a 10 for it, because the admins didn''t increase the scale for you submission further up.<br/> <br/>Honestly: even if the challenge topic would be ''still life'' or ''Show NO Water'' I would give it a 10. <br/>It''s extremely creative and a joy to look at. The composition is excellent, especially how you worked with the dark hair as part of the border and black background. The model is just beautiful and naturally looking. Like her smile very much and the clear haircut makes it too.<br/>Everything is crisp and clear, especially her face and of course the water fountain.<br/>But all these more technical aspects dont make the image, its the creativity that makes it so special. <br/>So to me for sure the winner and one of the ''All-Time-Best'' at DPC.</td>', 'I do have three problems with this image:1. To me it is more ''stopped action'' rather then action itself.2. It''''s another water drop image as there are plenty of.3. I only can give you a 10 for it, because the admins didn''t increase the scale for you submission further up. Honestly: even if the challenge topic would be ''still life'' or ''Show NO Water'' I would give it a 10. It''s extremely creative and a joy to look at. The composition is excellent, especially how you worked with the dark hair as part of the border and black background. The model is just beautiful and naturally looking. Like her smile very much and the clear haircut makes it too.Everything is crisp and clear, especially her face and of course the water fountain.But all these more technical aspects dont make the image, its the creativity that makes it so special. So to me for sure the winner and one of the ''All-Time-Best'' at DPC.', '2004-01-06 05:03:39.000000', NULL, 1),
(533128, 53751, 6999, '<td valign="top">Lots of good stuff here, though i think the feeling of spinning is actually missing - this looks more like a simple blurring - the feeling is the blurs don''t follow the curve of the globe. Neat idea though.</td>', 'Lots of good stuff here, though i think the feeling of spinning is actually missing - this looks more like a simple blurring - the feeling is the blurs don''t follow the curve of the globe. Neat idea though.', '2004-01-06 06:22:41.000000', NULL, 1),
(533130, 53442, 5158, '<td valign="top">I like the great combination of movment with stopped motion, very well thought.<br/>The cars and road in the miror are also well focused and sharp. <br/>Does need a little more contrast IMO and the border isn''t that good: it''s not necessary here. Good Luck</td>', 'I like the great combination of movment with stopped motion, very well thought.The cars and road in the miror are also well focused and sharp. Does need a little more contrast IMO and the border isn''t that good: it''s not necessary here. Good Luck', '2004-01-06 06:31:24.000000', NULL, 1),
(533131, 53477, 5158, '<td valign="top">Great combination of stoped and ongoing motion in this one. Also very joyfull. To me a little bright though and cropped too tight at the bottom. 8 from me.<br/></td>', 'Great combination of stoped and ongoing motion in this one. Also very joyfull. To me a little bright though and cropped too tight at the bottom. 8 from me.', '2004-01-06 06:33:32.000000', NULL, 1),
(533132, 53661, 5158, '<td valign="top">Veryy artistc aproach to the topic. I like that!<br/>Would have been nice to have at least a tiny part les blurred. I also thing that the addition of a border might be good on this one. A 8 from me.</td>', 'Veryy artistc aproach to the topic. I like that!Would have been nice to have at least a tiny part les blurred. I also thing that the addition of a border might be good on this one. A 8 from me.', '2004-01-06 06:35:38.000000', NULL, 1),
(533136, 53760, 5158, '<td valign="top">Very creative, fun to look at submission. It takes Action in the sence of stopped Action, which is OK to me. Like the background with its gradual change of brightnes, as well as the light on the model. Not shure if a different crop or format would have been better though. 8 from me.</td>', 'Very creative, fun to look at submission. It takes Action in the sence of stopped Action, which is OK to me. Like the background with its gradual change of brightnes, as well as the light on the model. Not shure if a different crop or format would have been better though. 8 from me.', '2004-01-06 06:38:45.000000', NULL, 1),
(533137, 53825, 5158, '<td valign="top">You have to tell us how you did that!<br/>Very creative. Light could be a little softer to reduce the reflexions and thus allow to increase the overall brightness. Also the the surface the poor pig stands on should be without any disturbances.<br/>Anyhow, very well done and good luck to you.</td>', 'You have to tell us how you did that!Very creative. Light could be a little softer to reduce the reflexions and thus allow to increase the overall brightness. Also the the surface the poor pig stands on should be without any disturbances.Anyhow, very well done and good luck to you.', '2004-01-06 06:41:51.000000', NULL, 1),
(533138, 53727, 5158, '<td valign="top">I really like the action in this one, very well captured. Also that almost everything beside the feets of the horses is sharp is great. The background disturbs a little but that wasn''t in your hands probably. Good luck</td>', 'I really like the action in this one, very well captured. Also that almost everything beside the feets of the horses is sharp is great. The background disturbs a little but that wasn''t in your hands probably. Good luck', '2004-01-06 06:43:29.000000', NULL, 1),
(533144, 53816, 14453, '<td valign="top">This is a very good picture. Your bird does''nt seems too much in action unfortunately!</td>', 'This is a very good picture. Your bird does''nt seems too much in action unfortunately!', '2004-01-06 07:13:53.000000', NULL, 1),
(533152, 53760, 4482, '<td valign="top">Nice shot... I think I might just recognize this model.  :-)  <br/> <br/>The roses add a special touch and the choice of BG color brings out the rest in the photo quite nicely. The only thing I keep saying to myself is... I wish the roses wouldn''t be so close to the model. :-)</td>', 'Nice shot... I think I might just recognize this model.  :-)   The roses add a special touch and the choice of BG color brings out the rest in the photo quite nicely. The only thing I keep saying to myself is... I wish the roses wouldn''t be so close to the model. :-)', '2004-01-06 07:25:30.000000', NULL, 1),
(533176, 53445, 15787, '<td valign="top">this are remarkable shots.... kids are really good subject .... great composition.... it may be simple but its a real action shot</td>', 'this are remarkable shots.... kids are really good subject .... great composition.... it may be simple but its a real action shot', '2004-01-06 08:08:21.000000', NULL, 1),
(533177, 53734, 12061, '<td valign="top">this was my highest rated photo for this weeks challenge. I think you did a wonderful job with it - I really have no suggestions to make this photo any better than it already is! Great work :)</td>', 'this was my highest rated photo for this weeks challenge. I think you did a wonderful job with it - I really have no suggestions to make this photo any better than it already is! Great work :)', '2004-01-06 08:10:40.000000', NULL, 1),
(533179, 53825, 12061, '<td valign="top">you have created a great freeze frame action shot here, my only comment is that the lighting and background could be improved. The lighting isn''t strong enough, and the background would look better if it were completely black. But supurb job with the action! WOW!</td>', 'you have created a great freeze frame action shot here, my only comment is that the lighting and background could be improved. The lighting isn''t strong enough, and the background would look better if it were completely black. But supurb job with the action! WOW!', '2004-01-06 08:12:40.000000', NULL, 1),
(533192, 53778, 327, '<td valign="top">Cute title. Maybe one second too soon?</td>', 'Cute title. Maybe one second too soon?', '2004-01-06 09:00:54.000000', NULL, 1),
(533194, 53539, 327, '<td valign="top">Cute moment, maybe a little dark?</td>', 'Cute moment, maybe a little dark?', '2004-01-06 09:01:32.000000', NULL, 1),
(533195, 53617, 327, '<td valign="top">Unique crop and pretty color.</td>', 'Unique crop and pretty color.', '2004-01-06 09:01:56.000000', NULL, 1),
(533231, 52646, 14614, '<td valign="top">Lovely b&amp;w</td>', 'Lovely b&w', '2004-01-06 10:03:43.000000', NULL, 1),
