(533253, 53661, 4338, '<td valign="top">i know the effect you were going for but for me anyway it is really hard to determine the subject in this image with the high amount of motion blur going on. To me it is to much of a distraction.</td>', 'i know the effect you were going for but for me anyway it is really hard to determine the subject in this image with the high amount of motion blur going on. To me it is to much of a distraction.', '2004-01-06 10:35:57.000000', NULL, 1),
(533255, 53539, 15137, '<td valign="top">Fun photo.  The bear actually looks embarassed.</td>', 'Fun photo.  The bear actually looks embarassed.', '2004-01-06 10:40:58.000000', NULL, 1),
(533263, 52780, 4338, '<td valign="top">very cool shot....great capture</td>', 'very cool shot....great capture', '2004-01-06 10:44:41.000000', NULL, 1),
(533265, 53734, 9504, '<td valign="top">WOW!  Simply fabulous...10</td>', 'WOW!  Simply fabulous...10', '2004-01-06 10:47:04.000000', NULL, 1),
(533273, 53692, 9504, '<td valign="top">This is wild...but you can tell it was highly post-edited.  The shadows are unnatural and it give this image an almost 3-D, surreal  quality. 8</td>', 'This is wild...but you can tell it was highly post-edited.  The shadows are unnatural and it give this image an almost 3-D, surreal  quality. 8', '2004-01-06 10:51:11.000000', NULL, 1),
