(534537, 53751, 8682, '<td valign="top">I like it. The idea is very original and the colours are beatiful, too. 7</td>', 'I like it. The idea is very original and the colours are beatiful, too. 7', '2004-01-07 10:15:04.000000', NULL, 1),
(534540, 53692, 8682, '<td valign="top">I´m not sure that the effect of the hockey player is really good to this photograph. It´s only my opinion.</td>', 'I´m not sure that the effect of the hockey player is really good to this photograph. It´s only my opinion.', '2004-01-07 10:15:56.000000', NULL, 1),
(534541, 53644, 8682, '<td valign="top">No doubt, it´s a really great picture. I like the sunset and the siluette of the fishers, but this picture gives me a calm sensation, not action... so I´m sorry but I´m not sure it meets the challenge 100%. But, as it is a great picture... 5</td>', 'No doubt, it´s a really great picture. I like the sunset and the siluette of the fishers, but this picture gives me a calm sensation, not action... so I´m sorry but I´m not sure it meets the challenge 100%. But, as it is a great picture... 5', '2004-01-07 10:17:16.000000', NULL, 1),
(534542, 53836, 8682, '<td valign="top">Wow, wow... it´s one of the best picture of this week. I love the effect of movement. Furthermore, the colours are very beatiful. One of my favs. 10</td>', 'Wow, wow... it´s one of the best picture of this week. I love the effect of movement. Furthermore, the colours are very beatiful. One of my favs. 10', '2004-01-07 10:18:17.000000', NULL, 1),
