(534819, 52844, 7350, '<td valign="top">Definitely one of my favorites of the challenge.  I love the crispness of this shot, and the obvious action.  Nice break, by the way!  10.</td>', 'Definitely one of my favorites of the challenge.  I love the crispness of this shot, and the obvious action.  Nice break, by the way!  10.', '2004-01-07 12:41:25.000000', NULL, 1),
(534823, 53734, 7350, '<td valign="top">This is a great idea.  Did you use a flash to "freeze" the water that way?  Your lighting and composition and focus are right on the money.  I hope this makes top 5!  10 from me.</td>', 'This is a great idea.  Did you use a flash to "freeze" the water that way?  Your lighting and composition and focus are right on the money.  I hope this makes top 5!  10 from me.', '2004-01-07 12:42:15.000000', NULL, 1),
(534826, 53756, 7350, '<td valign="top">This is the best of the bird shots in this challenge.  You almost captured an emotion of the bird here.  Good job!  10.</td>', 'This is the best of the bird shots in this challenge.  You almost captured an emotion of the bird here.  Good job!  10.', '2004-01-07 12:42:53.000000', NULL, 1),
