(535090, 53756, 12733, '<td valign="top">I see the aeriel, I''ll have to take your word for the assault. Great capture, nice composition and perfect focus and exposure.</td>', 'I see the aeriel, I''ll have to take your word for the assault. Great capture, nice composition and perfect focus and exposure.', '2004-01-07 14:44:51.000000', NULL, 1),
(535092, 53834, 12733, '<td valign="top">The blur works nicely to give the feeling of motion; the skates don''t show any metallic sheen and it took a minute to realize that they weren''t just boots. The loss of part of the forward skate was unfortunate.</td>', 'The blur works nicely to give the feeling of motion; the skates don''t show any metallic sheen and it took a minute to realize that they weren''t just boots. The loss of part of the forward skate was unfortunate.', '2004-01-07 14:46:58.000000', NULL, 1),
(535093, 52965, 12733, '<td valign="top">Nice snapshot - great expressions, but the other skater in the background is rally distracting and there''s more blur in the forward boy''s hands than I like to see.</td>', 'Nice snapshot - great expressions, but the other skater in the background is rally distracting and there''s more blur in the forward boy''s hands than I like to see.', '2004-01-07 14:48:16.000000', NULL, 1),
